// mosaic_platform_effects.dart -- Mosaic's platform library for Flutter
// (UI87 §7, §7.7): the native file dialogs, and the one call the generated
// main.dart makes to install the library on its host.
//
// Everything else -- the contract, the file I/O and the router -- is in
// `mosaic_platform_effects_core.dart`, which is plain Dart so a headless test
// can run it on the Dart VM; this file adds the one part that needs the
// Flutter engine. It re-exports the core, so an app (or its own handler) that
// imports this file sees the whole library.
//
// The dialogs are `package:file_selector`'s, published by the Flutter team:
// the native panel on macOS, the common item dialog on Windows and GTK's file
// chooser on Linux. A sandboxed macOS build needs the
// `com.apple.security.files.user-selected.read-write` entitlement for them;
// without it the panel fails and the request is answered
// `failed { "the file dialog failed" }`.

import 'package:file_selector/file_selector.dart';

import 'mosaic_host.dart';
import 'mosaic_platform_effects_core.dart';

export 'mosaic_platform_effects_core.dart';

/// `file_selector`'s dialogs. Returns full paths: the library reads and
/// writes through dart:io, so the bounded read and the temporary-then-move
/// save are the same code the headless test runs.
final class MosaicFileSelectorDialogs implements MosaicFileDialogs {
  const MosaicFileSelectorDialogs();

  @override
  Future<String?> chooseFileToOpen(List<String> extensions) async {
    final file = await openFile(acceptedTypeGroups: _groups(extensions));
    return file == null ? null : _localPath(file.path);
  }

  @override
  Future<String?> chooseFileToSave(
    String suggestedName,
    List<String> extensions,
  ) async {
    final location = await getSaveLocation(
      suggestedName: suggestedName,
      acceptedTypeGroups: _groups(extensions),
    );
    return location == null ? null : _localPath(location.path);
  }

  /// One group of the accepted extensions, or none at all -- "any file",
  /// which is what no accepted type means (UI59 §3). An empty group would be
  /// refused on Linux, which needs a filter in every group it is given.
  static List<XTypeGroup> _groups(List<String> extensions) => extensions.isEmpty
      ? const <XTypeGroup>[]
      : <XTypeGroup>[XTypeGroup(label: 'Files', extensions: extensions)];

  /// A choice with no local path cannot be read or written through dart:io,
  /// so it throws -- failed, not a cancel nobody made.
  static String _localPath(String path) {
    if (path.isEmpty) {
      throw StateError('the chosen file has no local path');
    }
    return path;
  }
}

/// Install the platform library on [host], after the package's own
/// `[host_effects]` handler (the router wraps whatever handler is set when it
/// installs, so that order is what lets the app's kinds reach the app).
/// [appKinds] is that handler's `kinds`, or null when it declared none.
///
/// Called by the generated main.dart right after the host is assigned, on
/// every start: a retried start is a new host, and gets a new router.
void installMosaicPlatformEffects(
  MosaicHost host, {
  required List<String>? appKinds,
}) {
  installMosaicPlatformRouter(
    MosaicHostEffects(host),
    appKinds: appKinds,
    dialogs: const MosaicFileSelectorDialogs(),
  );
}
